{
  "name": "oc-auth-switcher",
  "version": "1.0.4",
  "description": "OpenCode v2 plugin for multi-account Anthropic Claude Max rotation with automatic failover.",
  "type": "module",
  "main": "dist/index.js",
  "bin": {
    "oc-auth-switcher": "dist/cli.js"
  },
  "scripts": {
    "build": "bun build src/index.ts --outdir dist --target node --format esm && bun build src/cli.ts --outdir dist --target bun --format esm",
    "dev": "bun run build --watch",
    "test": "bun test",
    "prepublishOnly": "bun run build"
  },
  "dependencies": {
    "@ex-machina/opencode-anthropic-auth": "2.0.0-next.6"
  },
  "devDependencies": {
    "@opencode/plugin": "2.0.16",
    "@types/bun": "latest",
    "typescript": "^5.8.0"
  },
  "license": "MIT",
  "author": "ice",
  "repository": {
    "type": "git",
    "url": "https://github.com/grenaad/oc_auth_switcher"
  },
  "keywords": [
    "opencode",
    "anthropic",
    "claude",
    "multi-account",
    "auth",
    "plugin"
  ],
  "files": [
    "dist",
    "README.md",
    "LICENSE"
  ]
}
